import { PlaneGeometry, Group, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load texture for the plane ---
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // fallback surface
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // --- Plane geometry (512x320 aspect ~ 1.6:1) ---
  const geometry = new PlaneGeometry(1.6, 1.0);
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Text overlay ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (items.length > 0) {
    const item = items[0]; // headline
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2', // paper
      align: 'center',
    });
    textMesh.position.set(0, 0.15, 0.01); // slightly above plane surface
    group.add(textMesh);
  }

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // dispose loaded texture if assigned
    if (material.map) {
      material.map.dispose();
    }
    // dispose text resources if any
    group.children.forEach(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
